mapper.select:
SELECT sp.product_id AS productId, p.name AS productName, SUM(sp.quantity) AS quantity, COALESCE(SUM(sp.sales_amount), 0) AS salesAmount, SUM(sp.refund_quantity) AS refundQuantity, COALESCE(SUM(sp.refund_amount), 0) AS refundAmount, CASE WHEN SUM(sp.sales_amount) > 0 THEN ROUND(SUM(sp.refund_amount) / SUM(sp.sales_amount) * 100, 2) ELSE 0 END AS refundRate, ROUND(AVG(sp.exposure_conversion_rate), 2) AS exposureConversionRate, ROUND(AVG(sp.exposure_click_rate), 2) AS exposureClickRate, ROUND(AVG(sp.gpm), 2) AS gpm, ROUND(AVG(sp.click_payment_rate), 2) AS clickPaymentRate, COUNT(DISTINCT sp.session_id) AS sessionCount, COUNT(DISTINCT sp.company_id) AS companyCount, p.image_uri AS imageUri FROM session_product sp INNER JOIN live_session ls ON sp.session_id = ls.id AND ls.is_deleted = 0 LEFT JOIN product p ON sp.tenant_id = p.tenant_id AND sp.product_id = p.id AND p.is_deleted = 0 WHERE sp.tenant_id = #{req.tenantId} AND sp.is_deleted = 0 AND DATE(ls.start_time) BETWEEN #{req.startDate} AND #{req.endDate}
AND p.name LIKE CONCAT('%', #{req.productName}, '%')
AND sp.company_id = #{req.companyId}
AND sp.dept_id = #{req.deptId}
AND sp.team_id = #{req.teamId}
or sp.company_id in
#{id}
or sp.dept_id in
#{id}
or sp.team_id in
#{id}
GROUP BY sp.product_id, p.id ORDER BY
salesAmount quantity refundQuantity refundAmount refundRate exposureConversionRate exposureClickRate gpm clickPaymentRate sessionCount companyCount salesAmount
ASC DESC DESC
